layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16.25px; font-weight: 400; font-style: normal; line-height: 1.574; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 23.2px; transition: all; position: relative }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 4px 0px 0px 4px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: 0.2275px; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.574; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="section"] > h2 { color: rgb(16, 16, 16); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; line-height: 1.574; letter-spacing: 0.728px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(16, 16, 16); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #898989; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 30.5px; font-weight: 400; font-style: normal; line-height: 1.25; letter-spacing: 0.2135px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.35s }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.818; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 16px; padding-bottom: 4px; padding-left: 16px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: #898989; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15.25px; font-weight: 400; font-style: normal; line-height: 1.574; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: var(--ryt-bg) }
article[data-ryt="rec-card"]:hover { color: var(--ryt-bg) }
[data-ryt="pitch"]::before { content: ""; display: block; position: absolute; width: 9.59375px; height: 69.6875px; color: var(--ryt-text); background-color: rgba(148, 148, 148, 0.4); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 3px; font-family: var(--ryt-font-heading); font-size: 16.25px; font-weight: 400; font-style: normal; line-height: 1.574; letter-spacing: 0.2275px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
